package main

import (
	"bytes"
	"fmt"
	"runtime"
	"sync"
	"time"
)

// ---------- 1. 定义对象池 ----------
// New 是兜底构造函数：池中无可用对象时才调用
var bufPool = sync.Pool{
	New: func() any {
		// 预分配 64KB，避免复用过程中反复扩容
		return bytes.NewBuffer(make([]byte, 0, 64*1024))
	},
}

// ---------- 2. 业务函数：模拟高频序列化 ----------
func renderJSON(buf *bytes.Buffer, id int, name string) {
	buf.WriteString(`{"id":`)
	fmt.Fprintf(buf, "%d", id)
	buf.WriteString(`,"name":"`)
	buf.WriteString(name)
	buf.WriteString(`"}`)
}

// ---------- 3. 统计堆分配总量（字节） ----------
func measureAlloc(f func()) uint64 {
	var before, after runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&before)
	f()
	runtime.ReadMemStats(&after)
	return after.TotalAlloc - before.TotalAlloc // 累计分配差值
}

// ---------- 4. 对照组：每次现场分配 ----------
func withoutPool(n int) func() {
	return func() {
		for i := 0; i < n; i++ {
			buf := bytes.NewBuffer(make([]byte, 0, 64*1024)) // 每次都分配
			renderJSON(buf, i, "alice")
			_ = buf.Bytes()
		} // buf 立刻成为垃圾，等待 GC
	}
}

// ---------- 5. 实验组：复用 buffer ----------
func withPool(n int) func() {
	return func() {
		for i := 0; i < n; i++ {
			buf := bufPool.Get().(*bytes.Buffer) // 从池中取出（类型断言）
			buf.Reset()                          // 关键：清空内容但保留底层数组容量
			renderJSON(buf, i, "alice")
			_ = buf.Bytes()
			bufPool.Put(buf) // 用完归还，供其它 goroutine/后续迭代复用
		}
	}
}

func main() {
	const n = 200000

	start := time.Now()
	a1 := measureAlloc(withoutPool(n))
	t1 := time.Since(start)

	start = time.Now()
	a2 := measureAlloc(withPool(n))
	t2 := time.Since(start)

	fmt.Printf("无池: 分配 %.2f MB, 耗时 %v\n", float64(a1)/1024/1024, t1)
	fmt.Printf("有池: 分配 %.2f MB, 耗时 %v\n", float64(a2)/1024/1024, t2)
}
